"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { UsersIcon, XIcon } from "../parts/icons";
import { FileIcon, FolderIcon } from "./icons";
import { editedAgo, ITEMS, type ResultType, scoreOf, type SortKey, SORTS, type Team, TEAMS, TYPES } from "./search-results/data";
import { FacetGroup } from "./search-results/facet-group";
import { Highlight } from "./search-results/highlight";
import { QueryBox } from "./search-results/query-box";
import { ResultPreview } from "./search-results/result-preview";

const SETTLE_MS = 160;
// No overshoot: the fill glides to the next row and stops.
const GLIDE: Transition = { type: "spring", bounce: 0, duration: 0.25 };
const INSTANT: Transition = { duration: 0 };
const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };
const TYPE_ICON = { document: FileIcon, person: UsersIcon, file: FolderIcon } as const;

const toggleIn = <T,>(set: Set<T>, value: T, on: boolean) => {
  const next = new Set(set);
  if (on) next.add(value);
  else next.delete(value);
  return next;
};

/**
 * A workspace search page. Type a query, narrow it by type and team, sort
 * it, and read the chosen result in the preview. Facet counts follow the
 * query. A slash focuses the field from anywhere; arrows run from the
 * suggestions into the results.
 */
export function SearchResults({ className }: { className?: string }) {
  const titleId = useId();
  const listId = useId();
  const reduceMotion = useReducedMotion();
  const inputRef = useRef<HTMLInputElement | null>(null);
  const listRef = useRef<HTMLUListElement | null>(null);
  const [query, setQuery] = useState("reminder");
  const [committed, setCommitted] = useState("reminder");
  const [took, setTook] = useState<number | null>(null);
  const [types, setTypes] = useState<Set<ResultType>>(() => new Set());
  const [teams, setTeams] = useState<Set<Team>>(() => new Set());
  const [sort, setSort] = useState<SortKey>("best");
  const [active, setActive] = useState(0);
  const [selected, setSelected] = useState(0);

  // The search settles a moment after the last keystroke, as a real one would, and reports how long it took.
  useEffect(() => {
    if (query === committed) return;
    const started = performance.now();
    const timer = window.setTimeout(() => {
      setCommitted(query);
      setTook((performance.now() - started) / 1000);
      setActive(0);
      setSelected(0);
    }, SETTLE_MS);
    return () => window.clearTimeout(timer);
  }, [query, committed]);

  useEffect(() => {
    const onKey = (event: globalThis.KeyboardEvent) => {
      const target = event.target instanceof HTMLElement ? event.target : null;
      const typing = target?.closest("input, textarea, select, [contenteditable='true'], [role='dialog'], [role='menu']");
      if (event.key === "/" && !typing && !event.metaKey && !event.ctrlKey) {
        event.preventDefault();
        inputRef.current?.focus();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const matches = ITEMS.map((item) => ({ item, score: scoreOf(item, committed) })).filter((entry) => entry.score > 0);
  const results = matches
    .filter(({ item }) => (types.size === 0 || types.has(item.type)) && (teams.size === 0 || teams.has(item.team)))
    .sort((a, b) =>
      sort === "best" ? b.score - a.score : sort === "newest" ? a.item.editedDaysAgo - b.item.editedDaysAgo : a.item.title.localeCompare(b.item.title),
    )
    .map((entry) => entry.item);
  const typeOptions = TYPES.map((type) => ({ ...type, count: matches.filter(({ item }) => item.type === type.value).length }));
  const teamOptions = TEAMS.map((team) => ({ value: team, label: team, count: matches.filter(({ item }) => item.team === team).length }));
  const chips = [
    ...[...types].map((type) => ({ key: type, label: TYPES.find((option) => option.value === type)?.label ?? type, clear: () => setTypes((set) => toggleIn(set, type, false)) })),
    ...[...teams].map((team) => ({ key: team, label: team, clear: () => setTeams((set) => toggleIn(set, team, false)) })),
  ];
  const setKey = `${committed}|${[...types].join()}|${[...teams].join()}|${sort}`;
  const activeIndex = Math.min(active, results.length - 1);
  const preview = results[Math.min(selected, results.length - 1)] ?? null;

  const reset = () => {
    setActive(0);
    setSelected(0);
  };

  const onListKeyDown = (event: KeyboardEvent<HTMLUListElement>) => {
    let next: number;
    if (event.key === "ArrowDown") next = Math.min(results.length - 1, activeIndex + 1);
    else if (event.key === "ArrowUp") {
      if (activeIndex <= 0) {
        event.preventDefault();
        inputRef.current?.focus();
        return;
      }
      next = activeIndex - 1;
    } else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = results.length - 1;
    else return;
    event.preventDefault();
    setActive(next);
    setSelected(next);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-col gap-3 border-b border-border px-5 py-4">
        <h2 id={titleId} className="text-base font-semibold">
          Search Fernhill
        </h2>
        <QueryBox
          value={query}
          onChange={setQuery}
          onRun={(text) => {
            setQuery(text);
            inputRef.current?.focus();
          }}
          onEnterResults={() => listRef.current?.focus()}
          inputRef={inputRef}
        />
      </header>

      <div className="grid @3xl:grid-cols-[13rem_1fr] @5xl:grid-cols-[13rem_1fr_19rem]">
        <aside aria-label="Filters" className="grid grid-cols-2 gap-4 border-b border-border p-4 @3xl:flex @3xl:flex-col @3xl:border-r @3xl:border-b-0">
          <FacetGroup legend="Type" options={typeOptions} checked={types} onToggle={(value, on) => { setTypes((set) => toggleIn(set, value, on)); reset(); }} />
          <FacetGroup legend="Team" options={teamOptions} checked={teams} onToggle={(value, on) => { setTeams((set) => toggleIn(set, value, on)); reset(); }} />
        </aside>

        <div className="flex min-w-0 flex-col">
          <div className="flex flex-wrap items-center justify-between gap-3 px-4 pt-4">
            <p aria-live="polite" className="flex items-baseline gap-1 text-sm">
              <NumberTicker value={results.length} format={WHOLE} className="font-semibold" />
              <span>{results.length === 1 ? "result" : "results"}</span>
              {took !== null ? <span className="text-muted-foreground">in {took.toFixed(2)} seconds</span> : null}
            </p>
            <SegmentedControl aria-label="Sort results" options={SORTS} value={sort} onValueChange={(next) => { setSort(next); reset(); }} />
          </div>
          {chips.length > 0 ? (
            <ul aria-label="Active filters" className="flex flex-wrap gap-2 px-4 pt-3">
              {chips.map((chip) => (
                <li key={chip.key}>
                  <Button type="button" variant="outline" size="sm" onClick={chip.clear} aria-label={`Remove filter ${chip.label}`}>
                    {chip.label}
                    <XIcon aria-hidden="true" />
                  </Button>
                </li>
              ))}
            </ul>
          ) : null}

          <AnimatePresence mode="wait" initial={false}>
            <motion.div
              key={setKey}
              initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.14 }}
              className="p-2"
            >
              {results.length === 0 ? (
                <p className="px-3 py-10 text-center text-sm text-muted-foreground">Nothing matches. Try fewer words or remove a filter.</p>
              ) : (
                <ul
                  ref={listRef}
                  id={listId}
                  role="listbox"
                  aria-label="Results"
                  tabIndex={0}
                  aria-activedescendant={`${listId}-${results[activeIndex]?.id}`}
                  onKeyDown={onListKeyDown}
                  onPointerLeave={() => setActive(selected)}
                  className="flex flex-col rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  {results.map((item, index) => {
                    const Icon = TYPE_ICON[item.type];
                    return (
                      <li
                        key={item.id}
                        id={`${listId}-${item.id}`}
                        role="option"
                        aria-selected={index === Math.min(selected, results.length - 1)}
                        onPointerEnter={() => setActive(index)}
                        onClick={() => {
                          setSelected(index);
                          setActive(index);
                        }}
                        className="relative isolate flex cursor-pointer gap-3 rounded-xl px-3 py-3"
                      >
                        {index === activeIndex ? (
                          <motion.span layoutId={`${listId}-fill`} transition={reduceMotion ? INSTANT : GLIDE} aria-hidden="true" className="absolute inset-0 -z-10 rounded-xl bg-muted" />
                        ) : null}
                        <Icon aria-hidden="true" className={cn("mt-0.5 size-4 shrink-0", item.type === "person" ? "text-chart-2" : item.type === "file" ? "text-chart-4" : "text-chart-1")} />
                        <span className="flex min-w-0 flex-col gap-0.5">
                          <span className="truncate text-sm font-medium">
                            <Highlight text={item.title} query={committed} />
                          </span>
                          <span className="line-clamp-2 text-sm text-muted-foreground">
                            <Highlight text={item.snippet} query={committed} />
                          </span>
                          <span className="truncate text-xs text-muted-foreground">
                            {item.path.join(" / ")}. {item.editedBy}, {editedAgo(item.editedDaysAgo)}
                          </span>
                        </span>
                      </li>
                    );
                  })}
                </ul>
              )}
            </motion.div>
          </AnimatePresence>
        </div>

        <div className="border-t border-border @3xl:col-span-2 @5xl:col-span-1 @5xl:border-t-0 @5xl:border-l">
          <ResultPreview item={preview} query={committed} />
        </div>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

