/** The kinds of thing the workspace search finds. */
export type ResultType = "document" | "person" | "file";

/** The teams a result belongs to. */
export type Team = "Front desk" | "Clinical" | "Billing" | "Operations";

/** One thing the search can find. */
export interface SearchItem {
  id: string;
  type: ResultType;
  title: string;
  snippet: string;
  /** Where it lives, outermost first. */
  path: string[];
  team: Team;
  editedBy: string;
  /** Days since the last edit. */
  editedDaysAgo: number;
  /** The longer text the preview shows. */
  body: string;
}

/** The type facet, in the order the filter column shows it. */
