/** The sort orders. */
export type SortKey = "best" | "newest" | "name";

/** The sort choices, in the order the switch shows them. */
export const SORTS: { value: SortKey; label: string }[] = [
  { value: "best", label: "Best match" },
  { value: "newest", label: "Newest" },
  { value: "name", label: "A to Z" },
];

/** How well an item matches the query: 0 is no match, higher is better. An empty query matches everything a little. */
export function scoreOf(item: SearchItem, query: string): number {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (words.length === 0) return 1;
  let score = 0;
  for (const word of words) {
    const inTitle = item.title.toLowerCase().includes(word);
    const inSnippet = item.snippet.toLowerCase().includes(word) || item.path.join(" ").toLowerCase().includes(word);
    if (!inTitle && !inSnippet) return 0;
    score += inTitle ? 3 : 1;
  }
  return score;
}

/** How long ago an edit was, written short, such as "2 days ago". */
export function editedAgo(days: number): string {
  if (days === 0) return "today";
  if (days === 1) return "yesterday";
  if (days < 14) return `${days} days ago`;
  if (days < 60) return `${Math.round(days / 7)} weeks ago`;
  return `${Math.round(days / 30)} months ago`;
}

"use client";

import { NumberTicker } from "@/components/motion/number-ticker";
import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";

/** One choice in a facet, with how many results it holds for the current query. */
export interface FacetOption<T extends string = string> {
  value: T;
  label: string;
  count: number;
}

/** Props for one facet. */
export interface FacetGroupProps<T extends string> {
  legend: string;
  options: FacetOption<T>[];
  checked: Set<T>;
  onToggle: (value: T, on: boolean) => void;
}

const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

/** A group of checkboxes that narrow the results. Each count follows the query and rolls when it changes. */
export function FacetGroup<T extends string>({ legend, options, checked, onToggle }: FacetGroupProps<T>) {
  return (
    <fieldset className="flex min-w-0 flex-col gap-0.5">
      <legend className="mb-1 px-2 text-xs font-medium text-muted-foreground">{legend}</legend>
      {options.map((option) => {
        const on = checked.has(option.value);
        return (
          <label
            key={option.value}
            className={cn(
              "group relative isolate flex min-h-9 cursor-pointer items-center gap-2 rounded-lg px-2 text-sm has-focus-visible:ring-2 has-focus-visible:ring-ring",
              option.count === 0 && !on && "text-muted-foreground",
            )}
          >
            <span aria-hidden="true" className="absolute inset-0 -z-10 rounded-lg group-hover:bg-muted/50" />
            <Checkbox checked={on} onCheckedChange={(value) => onToggle(option.value, value === true)} aria-label={`${option.label}, ${option.count} results`} />
            <span className="min-w-0 flex-1 truncate">{option.label}</span>
            <NumberTicker value={option.count} format={WHOLE} aria-hidden="true" className="text-xs text-muted-foreground" />
          </label>
        );
      })}
    </fieldset>
  );
}

/** Props for text with the query's words marked. */
export interface HighlightProps {
  text: string;
  query: string;
}

const escape = (word: string) => word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/** Shows `text` with every word of the query marked, so a person sees why it matched. */
export function Highlight({ text, query }: HighlightProps) {
  const words = query.split(/\s+/).filter(Boolean).map(escape);
  if (words.length === 0) return <>{text}</>;
  const pattern = new RegExp(`(${words.join("|")})`, "gi");
  return (
    <>
      {text.split(pattern).map((part, index) =>
        index % 2 === 1 ? (
          <mark key={index} className="rounded-sm bg-marketing-amber-surface px-0.5 text-marketing-amber-ink">
            {part}
          </mark>
        ) : (
          part
        ),
      )}
    </>
  );
}

"use client";

import { type KeyboardEvent, type RefObject, useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { XIcon } from "../../parts/icons";
import { ClockIcon, SearchIcon } from "../icons";
import { RECENT, SUGGESTED } from "./data";

/** Props for the search field and its suggestions. */
export interface QueryBoxProps {
  value: string;
  onChange: (value: string) => void;
  /** Runs a suggestion: the field takes its text. */
  onRun: (value: string) => void;
  /** Moves the keyboard from the field into the results. */
  onEnterResults: () => void;
  inputRef: RefObject<HTMLInputElement | null>;
}

/**
 * The query field. While it has focus it lists recent and suggested
 * searches that start with what is typed. Arrows move through them and then
 * into the results; Enter runs the highlighted one; Escape closes the list.
 */
export function QueryBox({ value, onChange, onRun, onEnterResults, inputRef }: QueryBoxProps) {
  const listId = useId();
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const typed = value.trim().toLowerCase();
  const match = (option: string) => option.toLowerCase().startsWith(typed) && option.toLowerCase() !== typed;
  const options = [
    ...RECENT.filter(match).map((text) => ({ text, kind: "recent" as const })),
    ...SUGGESTED.filter(match).map((text) => ({ text, kind: "suggested" as const })),
  ];
  const showing = open && options.length > 0;

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "ArrowDown") {
      event.preventDefault();
      if (!showing || active >= options.length - 1) {
        setOpen(false);
        setActive(-1);
        onEnterResults();
      } else setActive(active + 1);
    } else if (event.key === "ArrowUp" && showing) {
      event.preventDefault();
      setActive(Math.max(-1, active - 1));
    } else if (event.key === "Enter") {
      event.preventDefault();
      const option = options[active];
      if (showing && option) onRun(option.text);
      setOpen(false);
      setActive(-1);
    } else if (event.key === "Escape" && showing) {
      event.preventDefault();
      setOpen(false);
      setActive(-1);
    }
  };

  return (
    <div className="relative flex items-center gap-2">
      <SearchIcon aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
      <Input
        ref={inputRef}
        type="text"
        role="combobox"
        aria-label="Search the workspace"
        aria-expanded={showing}
        aria-controls={listId}
        aria-autocomplete="list"
        aria-activedescendant={showing && active >= 0 ? `${listId}-${active}` : undefined}
        placeholder="Search documents, people and files"
        value={value}
        onChange={(event) => {
          onChange(event.target.value);
          setOpen(true);
          setActive(-1);
        }}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
        onKeyDown={onKeyDown}
        className="h-11 flex-1"
      />
      <span className="flex w-9 shrink-0 items-center justify-center">
        {value ? (
          <Button type="button" variant="ghost" size="icon" aria-label="Clear the search" onClick={() => onRun("")} className="size-8">
            <XIcon aria-hidden="true" />
          </Button>
        ) : (
          <kbd aria-hidden="true" title="Press / to search" className="rounded border border-border px-1.5 text-xs text-muted-foreground">
            /
          </kbd>
        )}
      </span>
      {showing ? (
        <ul
          id={listId}
          role="listbox"
          aria-label="Searches"
          className="absolute inset-x-0 top-full z-20 mt-1 flex flex-col gap-0.5 rounded-xl border border-border bg-popover p-1 text-popover-foreground shadow-lg backdrop-blur-md"
        >
          {options.map((option, index) => (
            <li
              key={option.text}
              id={`${listId}-${index}`}
              role="option"
              aria-selected={index === active}
              onPointerDown={(event) => {
                event.preventDefault();
                onRun(option.text);
                setOpen(false);
              }}
              onPointerEnter={() => setActive(index)}
              className={cn("flex cursor-pointer items-center gap-2 rounded-lg px-3 py-2 text-sm", index === active && "bg-muted")}
            >
              {option.kind === "recent" ? (
                <ClockIcon aria-hidden="true" className="size-4 text-muted-foreground" />
              ) : (
                <SearchIcon aria-hidden="true" className="size-4 text-muted-foreground" />
              )}
              {option.text}
              <span className="ml-auto text-xs text-muted-foreground">{option.kind === "recent" ? "Recent" : "Suggested"}</span>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

import { Button } from "@/components/ui/button";

import { UsersIcon } from "../../parts/icons";
import { FileIcon, FolderIcon } from "../icons";
import { editedAgo, type SearchItem } from "./data";
import { Highlight } from "./highlight";

/** Props for the preview pane. */
export interface ResultPreviewProps {
  item: SearchItem | null;
  query: string;
}

const KIND = { document: "Document", person: "Person", file: "File" } as const;

/** The selected result in full: its type, path, text and who edited it last, with an action to open it. */
export function ResultPreview({ item, query }: ResultPreviewProps) {
  if (!item) {
    return <p className="p-5 text-sm text-muted-foreground">Choose a result to see it here.</p>;
  }
  const Icon = item.type === "person" ? UsersIcon : item.type === "file" ? FolderIcon : FileIcon;
  return (
    <article aria-label={`Preview of ${item.title}`} className="flex flex-col gap-3 p-5">
      <span className="flex items-center gap-2 text-xs text-muted-foreground">
        <Icon aria-hidden="true" className="size-4" />
        {KIND[item.type]} in {item.path.join(" / ")}
      </span>
      <h3 className="text-base font-semibold break-words">
        <Highlight text={item.title} query={query} />
      </h3>
      <p className="text-sm leading-relaxed">
        <Highlight text={item.body} query={query} />
      </p>
      <p className="text-xs text-muted-foreground">
        {item.team}. Edited by {item.editedBy} {editedAgo(item.editedDaysAgo)}.
      </p>
      <Button type="button" variant="outline" size="sm" className="self-start">
        {item.type === "person" ? "Open profile" : "Open"}
      </Button>
    </article>
  );
}
